-- Chantier "Personnages" (app mobile) -- contenu D&D, lot 4 (relu par le chef de projet).
-- Complete public.class_features avec la progression multi-niveaux des sous-classes
-- hors SRD (license_status official_needs_verification dans class_features.json),
-- reformulee en texte original (jamais copie du livre) -- voir
-- scripts/class_features_non_srd_draft.json pour la trace complete, y compris les
-- 8 corrections factuelles faites en relecture par le chef de projet avant cette
-- migration (ex. "Aspect de la bete" Aigle confondait niveau 6 et niveau 14 ;
-- "Benediction de l'escroc"/"Linceul d'ombre"/"Pretre de guerre" du Clerc
-- decrivaient un effet mecaniquement different du RAW ; "Esprit eveille" de
-- l'Occultiste inventait un prerequis de langue commune qui n'existe pas RAW ;
-- type de degats de "Frappe divine" corrige pour Guerre/Duperie).
--
-- Occultiste "Le Genie" : le fichier source ne detaille pas les 4 variantes
-- (Dao/Djinn/Efrit/Maride) separement (mecanique de patron partagee, seul le
-- talent elementaire differe, deja hors perimetre de ce lot) -- les 10 lignes
-- du fichier pour "Le Genie" sont donc dupliquees sur les 4 sous-classes deja
-- en base (Genie - Dao/Djinn/Efrit/Maride, ids 76-79).
--
-- Paladin "Serment des anciens" (subclass_id=7) : c'est la sous-classe
-- "iconique" posee en Phase 1 pour ce serment (PAS le Serment de devotion
-- SRD, id=83, deja complete au lot 2) -- non-SRD comme les autres de ce lot.
--
-- Dedoublonnage par subclass_id + niveau + nom (idempotent, comme le lot 2).

do $$
declare
  rec record;
  v_id int;
begin
  for rec in
    select * from (values
      (13, 3, $q$Quêteur spirituel$q$, $q$Vous pouvez lancer les rituels invocation d'animaux ou communication avec les animaux, mais seulement sous forme de rituel.$q$, null, null::jsonb),
      (13, 3, $q$Esprit totem$q$, $q$Vous choisissez un esprit totem (Ours, Aigle ou Loup) qui vous octroie un bénéfice tant que vous êtes en rage : Ours (résistance à tous les dégâts sauf psychiques), Aigle (désavantage aux attaques d'opportunité contre vous et action bonus pour Foncer), ou Loup (vos alliés ont l'avantage aux attaques de mêlée contre une créature à 1,50 m de vous).$q$, null, null::jsonb),
      (13, 6, $q$Aspect de la bête$q$, $q$Vous gagnez un bénéfice permanent lié à votre esprit totem, même hors rage : Ours (force portée doublée, avantage aux tests de Force), Aigle (vous voyez jusqu'à 1,6 km sans difficulté et la pénombre ne vous impose pas de désavantage aux tests de Sagesse (Perception) fondés sur la vue), ou Loup (pistage à vitesse normale et déplacement furtif en groupe même à vitesse normale).$q$, null, null::jsonb),
      (13, 10, $q$Marcheur spirituel$q$, $q$Vous pouvez lancer le rituel communion avec la nature ; en le lançant ainsi, vous invoquez à la place un esprit spectral qui prend la forme de votre animal totem pour répondre à vos questions.$q$, null, null::jsonb),
      (13, 14, $q$Lien totémique$q$, $q$Tant que vous êtes en rage, vous gagnez un bénéfice supplémentaire puissant lié à votre esprit totem : Ours (vos alliés à 9 m gagnent la résistance à tous les dégâts sauf psychiques), Aigle (vitesse de vol égale à la vitesse de marche), ou Loup (vos attaques réussies mettent une grande créature à terre).$q$, null, null::jsonb),
      (18, 3, $q$Sens de la magie$q$, $q$Par une action, vous savez si un sort a été lancé à 18 m de vous au cours du dernier round, sans en connaître l'école ni la source exacte.$q$, null, null::jsonb),
      (18, 3, $q$Sursaut sauvage$q$, $q$Chaque fois que vous entrez en rage, vous lancez sur la table Éruption sauvage (d8) pour déclencher un effet magique aléatoire touchant vous-même et les créatures proches.$q$, null, null::jsonb),
      (18, 6, $q$Réserve de magie$q$, $q$Vous pouvez dépenser un dé d'Éruption sauvage non utilisé pour donner à une créature à 18 m un avantage à son prochain jet d'attaque, de sauvegarde ou de caractéristique.$q$, null, null::jsonb),
      (18, 10, $q$Réaction instable$q$, $q$En réaction lorsque vous subissez des dégâts d'une attaque ou ratez un jet de sauvegarde alors que vous êtes en rage, vous pouvez relancer sur la table Éruption sauvage.$q$, null, null::jsonb),
      (18, 14, $q$Sursaut contrôlé$q$, $q$Lorsque vous lancez sur la table Éruption sauvage, vous pouvez lancer deux fois et choisir l'un des deux résultats.$q$, null, null::jsonb),
      (20, 3, $q$Maîtrises supplémentaires$q$, $q$Vous gagnez la maîtrise des armures intermédiaires, des boucliers et des armes de guerre.$q$, null, null::jsonb),
      (20, 3, $q$Inspiration martiale$q$, $q$Une créature qui utilise votre dé d'Inspiration bardique sur un jet d'attaque peut ajouter le dé aux dégâts infligés par l'attaque en cas de réussite.$q$, null, null::jsonb),
      (20, 6, $q$Attaque supplémentaire$q$, $q$Vous pouvez attaquer deux fois, au lieu d'une, chaque fois que vous effectuez l'action Attaquer à votre tour.$q$, null, null::jsonb),
      (20, 14, $q$Magie de combat$q$, $q$Quand vous utilisez votre action pour lancer un sort de barde, vous pouvez effectuer une attaque avec une arme en action bonus.$q$, null, null::jsonb),
      (27, 1, $q$Sorts de domaine (Niveau de clerc 1)$q$, $q$Sorts de domaine toujours préparés, gagnés automatiquement à ce niveau de clerc (ne comptent pas dans le nombre de sorts préparés) : Charme-personne, Déguisement.$q$, $q$sort_domaine$q$, null::jsonb),
      (27, 3, $q$Sorts de domaine (Niveau de clerc 3)$q$, $q$Sorts de domaine toujours préparés : Reflets troublants, Passage sans trace.$q$, $q$sort_domaine$q$, null::jsonb),
      (27, 5, $q$Sorts de domaine (Niveau de clerc 5)$q$, $q$Sorts de domaine toujours préparés : Clignotement, Dissipation de la magie.$q$, $q$sort_domaine$q$, null::jsonb),
      (27, 7, $q$Sorts de domaine (Niveau de clerc 7)$q$, $q$Sorts de domaine toujours préparés : Porte dimensionnelle, Métamorphose.$q$, $q$sort_domaine$q$, null::jsonb),
      (27, 9, $q$Sorts de domaine (Niveau de clerc 9)$q$, $q$Sorts de domaine toujours préparés : Domination de personne, Modification de la mémoire.$q$, $q$sort_domaine$q$, null::jsonb),
      (27, 1, $q$Bénédiction de l'escroc$q$, $q$Par un rituel, vous touchez une créature consentante pour lui accorder l'avantage aux tests de Discrétion pendant 1 heure ; utilisable de nouveau seulement en répétant le rituel (annule l'effet précédent).$q$, null, null::jsonb),
      (27, 2, $q$Conduit divin : invocation de réplique$q$, $q$Vous utilisez votre Conduit divin pour créer une illusion parfaite de vous-même qui dure 1 minute et peut se déplacer et parler à votre place.$q$, null, null::jsonb),
      (27, 6, $q$Conduit divin : linceul d'ombre$q$, $q$Par une action, vous utilisez votre Conduit divin pour devenir invisible jusqu'à la fin de votre prochain tour ; vous redevenez visible si vous attaquez ou lancez un sort.$q$, null, null::jsonb),
      (27, 8, $q$Frappe divine$q$, $q$Une fois par tour, vous pouvez ajouter 1d8 dégâts de poison (2d8 au niveau 14) sur une attaque d'arme réussie.$q$, null, null::jsonb),
      (27, 17, $q$Réplique améliorée$q$, $q$Votre réplique illusoire (voir Invocation de réplique) peut désormais lancer les sorts que vous lui avez préparés en votre nom, en utilisant vos emplacements de sorts.$q$, null, null::jsonb),
      (28, 1, $q$Sorts de domaine (Niveau de clerc 1)$q$, $q$Sorts de domaine toujours préparés : Faveur divine, Bouclier de la foi.$q$, $q$sort_domaine$q$, null::jsonb),
      (28, 3, $q$Sorts de domaine (Niveau de clerc 3)$q$, $q$Sorts de domaine toujours préparés : Arme magique, Arme spirituelle.$q$, $q$sort_domaine$q$, null::jsonb),
      (28, 5, $q$Sorts de domaine (Niveau de clerc 5)$q$, $q$Sorts de domaine toujours préparés : Manteau du croisé, Gardiens spirituels.$q$, $q$sort_domaine$q$, null::jsonb),
      (28, 7, $q$Sorts de domaine (Niveau de clerc 7)$q$, $q$Sorts de domaine toujours préparés : Liberté de mouvement, Peau de pierre.$q$, $q$sort_domaine$q$, null::jsonb),
      (28, 9, $q$Sorts de domaine (Niveau de clerc 9)$q$, $q$Sorts de domaine toujours préparés : Frappe flamboyante, Immobilisation de monstre.$q$, $q$sort_domaine$q$, null::jsonb),
      (28, 1, $q$Maîtrises supplémentaires$q$, $q$Vous gagnez la maîtrise des armures lourdes et des armes de guerre.$q$, null, null::jsonb),
      (28, 1, $q$Prêtre de guerre$q$, $q$Quand vous utilisez l'action Attaquer, vous pouvez effectuer une attaque d'arme supplémentaire en action bonus. Utilisable un nombre de fois égal à votre modificateur de Sagesse (minimum 1) par repos long.$q$, null, null::jsonb),
      (28, 2, $q$Conduit divin : frappe guidée$q$, $q$Vous utilisez votre Conduit divin pour gagner +10 à un jet d'attaque que vous venez d'effectuer, après en avoir vu le résultat mais avant de connaître son issue.$q$, null, null::jsonb),
      (28, 6, $q$Conduit divin : bénédiction du dieu de la guerre$q$, $q$Vous utilisez votre Conduit divin, en réaction, pour donner à une créature à 9 m un bonus de +10 à un jet d'attaque qu'elle vient d'effectuer.$q$, null, null::jsonb),
      (28, 8, $q$Frappe divine$q$, $q$Une fois par tour, vos attaques d'arme infligent 1d8 dégâts supplémentaires du même type que l'arme utilisée (2d8 au niveau 14).$q$, null, null::jsonb),
