      (29, 1, $q$Sort mineur supplémentaire$q$, $q$Vous connaissez le cantrip Lumière en plus des cantrips normalement connus à ce niveau.$q$, $q$sort_mineur_bonus$q$, null::jsonb),
      (29, 1, $q$Illumination protectrice$q$, $q$En réaction lorsqu'une créature à 9 m de vous subit des dégâts, vous pouvez réduire ces dégâts de 1d8 + votre niveau de clerc.$q$, null, null::jsonb),
      (29, 2, $q$Conduit divin : radiance de l'aube$q$, $q$Vous utilisez votre Conduit divin pour libérer une lumière matinale qui inflige 2d10 + votre niveau de clerc dégâts radiants aux ennemis dans un rayon de 9 m et dissipe l'obscurité magique.$q$, null, null::jsonb),
