      (31, 9, $q$Sorts de domaine (Niveau de clerc 9)$q$, $q$Sorts de domaine toujours préparés : Connaissance des légendes, Scrutation.$q$, $q$sort_domaine$q$, null::jsonb),
      (31, 1, $q$Bénédictions du savoir$q$, $q$Vous gagnez la maîtrise de deux compétences parmi Arcanes, Histoire, Nature ou Religion, et vous doublez votre bonus de maîtrise pour ces compétences.$q$, null, null::jsonb),
      (31, 2, $q$Conduit divin : savoir ancestral$q$, $q$Vous utilisez votre Conduit divin pour obtenir l'avantage à un test de caractéristique lié à l'Histoire, ou pour gagner la maîtrise d'une compétence pendant 10 minutes.$q$, null, null::jsonb),
      (31, 6, $q$Conduit divin : lecture des pensées$q$, $q$Vous utilisez votre Conduit divin pour lire les pensées superficielles d'une créature pendant 5 minutes ; vous pouvez ensuite tenter de sonder plus profondément (JdS d'Intelligence) ou implanter un souvenir suggéré.$q$, null, null::jsonb),
