      (34, 1, $q$Maîtrises supplémentaires$q$, $q$Vous gagnez la maîtrise des armures lourdes et des outils de forgeron.$q$, null, null::jsonb),
      (34, 1, $q$Bénédiction de la forge$q$, $q$Par un rituel nocturne, vous rendez magique une arme ou une armure non magique (+1 CA ou +1 aux dégâts selon le cas). Cette bénédiction dure jusqu'à ce que vous répétiez le rituel sur un autre objet.$q$, null, null::jsonb),
