      (36, 2, $q$Forme sauvage de combat$q$, $q$Vous pouvez utiliser votre Forme sauvage comme action bonus (au lieu d'une action) et dépenser des emplacements de sorts pour récupérer des points de vie temporaires en changeant de forme.$q$, null, null::jsonb),
      (36, 2, $q$Formes du cercle$q$, $q$Votre Forme sauvage vous permet de prendre l'apparence de bêtes de FP plus élevé que la normale (jusqu'à FP 1 au niveau 2, augmentant avec votre niveau de druide).$q$, null, null::jsonb),
