      (42, 6, $q$Chance forcée$q$, $q$Une fois par repos long, vous pouvez transformer un échec en réussite lors d'un jet de sauvegarde, mais vous déclenchez alors un effet de la table Éruption sauvage.$q$, null, null::jsonb),
      (42, 14, $q$Chaos contrôlé$q$, $q$Quand vous déclenchez un effet de la table Éruption sauvage, vous pouvez lancer deux fois et choisir l'un des deux résultats.$q$, null, null::jsonb),
      (42, 18, $q$Bombardement de sort$q$, $q$Quand vous infligez des dégâts avec un sort d'ensorceleur et obtenez le résultat le plus bas possible sur au moins un dé de dégâts, vous pouvez relancer ce dé, potentiellement plusieurs fois en chaîne.$q$, null, null::jsonb),
      (48, 3, $q$Disciple martial$q$, $q$Vous apprenez trois manœuvres de combat de votre choix et gagnez des dés de supériorité (d8) pour les alimenter.$q$, null, null::jsonb),
      (48, 3, $q$Supériorité martiale$q$, $q$Vous disposez de 4 dés de supériorité (d8), qui augmentent en nombre et en taille à des niveaux supérieurs ; vous les regagnez tous en terminant un repos court ou long.$q$, $q$manoeuvre$q$, '{"amount": 4, "rest_type": "repos_court"}'::jsonb),
      (48, 7, $q$Observation de l’ennemi$q$, $q$Par une action bonus, vous pouvez étudier une créature visible pour en apprendre les forces et faiblesses relatives (une des six caractéristiques la plus haute/basse, ou immunités/résistances/vulnérabilités).$q$, null, null::jsonb),
      (48, 10, $q$Supériorité martiale améliorée$q$, $q$Vos dés de supériorité passent au d10, puis au d12 au niveau 18.$q$, null, null::jsonb),
      (48, 15, $q$Implacable$q$, $q$Quand vous ratez un jet d'attaque avec une arme lors de votre tour, vous pouvez, une fois par repos court ou long, refaire immédiatement le jet.$q$, null, null::jsonb),
      (48, 3, $q$Manœuvres$q$, $q$Vous choisissez des manœuvres martiales parmi une liste (ex. Attaque précise, Feinte, Parade...) qui ajoutent un effet spécial en dépensant un dé de supériorité, avec un DD de sauvegarde égal à 8 + bonus de maîtrise + modificateur de Force ou Dextérité.$q$, null, null::jsonb),
      (49, 3, $q$Incantation$q$, $q$Vous apprenez à lancer des sorts de magicien (école d'évocation et d'abjuration principalement), en utilisant l'Intelligence comme caractéristique d'incantation, avec une progression de sorts lente (un tiers du niveau de guerrier).$q$, null, null::jsonb),
      (49, 3, $q$Lien avec une arme$q$, $q$Vous liez rituellement une arme à vous-même : vous ne pouvez pas en être désarmé sans le vouloir et pouvez la faire apparaître en main par une action bonus si elle se trouve sur le même plan d'existence.$q$, null, null::jsonb),
      (49, 7, $q$Magie de guerre$q$, $q$Quand vous utilisez votre action pour lancer un cantrip, vous pouvez effectuer une attaque avec une arme en action bonus.$q$, null, null::jsonb),
      (49, 10, $q$Frappe occulte$q$, $q$Une fois par tour, quand vous touchez une créature avec votre arme liée, vous pouvez la piéger magiquement (JdS d'Intelligence) lui imposant un désavantage aux jets de sauvegarde contre vos sorts jusqu'à la fin de votre prochain tour.$q$, null, null::jsonb),
      (49, 15, $q$Charge arcanique$q$, $q$Quand vous utilisez Fougue guerrière, vous pouvez vous téléporter jusqu'à 9 m vers un espace inoccupé visible avant ou après chaque attaque supplémentaire.$q$, null, null::jsonb),
      (49, 18, $q$Magie de guerre améliorée$q$, $q$Quand vous utilisez votre action pour lancer un sort de magicien, vous pouvez effectuer une attaque avec une arme en action bonus.$q$, null, null::jsonb),
      (55, 2, $q$Abjurateur érudit$q$, $q$L'or et le temps nécessaires pour copier un sort d'abjuration dans votre grimoire sont réduits de moitié.$q$, null, null::jsonb),
      (55, 2, $q$Protection arcanique$q$, $q$Quand vous lancez un sort d'abjuration de niveau 1 ou plus, vous créez un bouclier magique qui absorbe des dégâts (2 x niveau du sort + votre niveau de magicien) jusqu'à épuisement ou fin d'un repos long.$q$, null, '{"amount": 1, "rest_type": "repos_long"}'::jsonb),
      (55, 6, $q$Protection projetée$q$, $q$Vous pouvez utiliser votre réaction pour transférer les dégâts absorbés par votre Protection arcanique sur une autre créature à 9 m que vous pouvez voir.$q$, null, null::jsonb),
      (55, 10, $q$Abjuration améliorée$q$, $q$Quand vous créez votre Protection arcanique, vous pouvez choisir jusqu'à deux créatures supplémentaires à 9 m qui bénéficient chacune de leur propre réserve de points d'absorption.$q$, null, null::jsonb),
      (55, 14, $q$Résistance aux sorts$q$, $q$Vous avez l'avantage aux jets de sauvegarde contre les sorts, et vous êtes résistant aux dégâts infligés par les sorts des autres créatures.$q$, null, null::jsonb),
      (56, 2, $q$Devin érudit$q$, $q$L'or et le temps nécessaires pour copier un sort de divination dans votre grimoire sont réduits de moitié.$q$, null, null::jsonb),
      (56, 2, $q$Présage$q$, $q$Après un repos court ou long, vous lancez deux d20 et notez les résultats ; vous pouvez ensuite les substituer à un jet d'attaque, de caractéristique ou de sauvegarde vous concernant ou concernant une créature proche.$q$, null, '{"amount": 2, "rest_type": "repos_long"}'::jsonb),
      (56, 6, $q$Divination experte$q$, $q$Quand vous lancez un sort de divination utilisant un emplacement de niveau 2 ou plus, vous récupérez un emplacement de sort d'un niveau inférieur.$q$, null, null::jsonb),
      (56, 10, $q$Troisième œil$q$, $q$Par une action, vous gagnez l'un des sens suivants jusqu'à la fin de votre tour (sans dépense) : vision dans le noir, vue éthérée, détection des invisibles, ou lecture de toute langue.$q$, null, null::jsonb),
      (56, 14, $q$Présage supérieur$q$, $q$Vous obtenez trois d20 pour votre Présage (au lieu de deux) et pouvez en utiliser plus d'un pour un même jet.$q$, null, null::jsonb),
      (57, 2, $q$Enchanteur érudit$q$, $q$L'or et le temps nécessaires pour copier un sort d'enchantement dans votre grimoire sont réduits de moitié.$q$, null, null::jsonb),
      (57, 2, $q$Regard hypnotique$q$, $q$Par une action, vous pouvez tenter d'hypnotiser une créature que vous voyez à 1,50 m (JdS de Sagesse) ; en cas d'échec, elle est incapable d'agir jusqu'à la fin de votre prochain tour.$q$, null, null::jsonb),
      (57, 6, $q$Charme instinctif$q$, $q$Une fois par tour, en réaction, vous pouvez rediriger une attaque contre vous vers une autre créature à 1,50 m (JdS de Sagesse pour l'attaquant, sinon la nouvelle cible est visée).$q$, null, null::jsonb),
      (57, 10, $q$Partage d'enchantement$q$, $q$Quand vous lancez un sort d'enchantement de niveau 1 ou plus qui ne cible qu'une créature, vous pouvez viser une seconde créature à 9 m.$q$, null, null::jsonb),
      (57, 14, $q$Altération mémorielle$q$, $q$Vous pouvez lancer le sort modification de la mémoire sans dépenser d'emplacement de sort, une fois par repos long.$q$, null, null::jsonb),
      (58, 2, $q$Illusionniste érudit$q$, $q$L'or et le temps nécessaires pour copier un sort d'illusion dans votre grimoire sont réduits de moitié.$q$, null, null::jsonb),
      (58, 2, $q$Illusion mineure améliorée$q$, $q$Votre cantrip Illusion mineure gagne deux effets supplémentaires au choix chaque fois que vous le lancez.$q$, null, null::jsonb),
      (58, 6, $q$Illusions malléables$q$, $q$Vous pouvez modifier à distance l'illusion créée par un de vos sorts, changeant sa nature dans les limites du sort d'origine.$q$, null, null::jsonb),
      (58, 10, $q$Double illusoire$q$, $q$Par une action, vous créez une illusion parfaite de vous-même à 1,50 m qui dure jusqu'à ce qu'elle soit dissipée ; vous pouvez échanger vos places avec elle magiquement.$q$, null, '{"amount": 1, "rest_type": "repos_court"}'::jsonb),
      (58, 14, $q$Réalité illusoire$q$, $q$Une fois par sort d'illusion lancé, vous pouvez rendre un objet non magique inclus dans l'illusion réel pendant 1 minute.$q$, null, null::jsonb),
      (59, 2, $q$Invocateur érudit$q$, $q$L'or et le temps nécessaires pour copier un sort d'invocation dans votre grimoire sont réduits de moitié.$q$, null, null::jsonb),
      (59, 2, $q$Invocation mineure$q$, $q$Par une action et une composante matérielle sans valeur, vous invoquez une créature spectrale minuscule qui vous obéit pendant 1 heure.$q$, null, null::jsonb),
      (59, 6, $q$Permutation$q$, $q$Quand vous lancez un sort d'invocation de niveau 1 ou plus, vous pouvez remplacer une de ses composantes matérielles non coûteuses par un geste ou une formule.$q$, null, '{"amount": 1, "rest_type": "repos_long"}'::jsonb),
      (59, 10, $q$Invocation consciencieuse$q$, $q$Quand vous invoquez une créature par un sort, elle gagne des points de vie temporaires égaux à votre niveau de magicien.$q$, null, null::jsonb),
      (59, 14, $q$Convocations coriaces$q$, $q$Les créatures que vous invoquez par un sort d'invocation sont résistantes à tous les dégâts pendant la durée du sort.$q$, null, null::jsonb),
      (60, 2, $q$Nécromancien érudit$q$, $q$L'or et le temps nécessaires pour copier un sort de nécromancie dans votre grimoire sont réduits de moitié.$q$, null, null::jsonb),
      (60, 2, $q$Sinistre moisson$q$, $q$Quand vous tuez une créature avec un sort de niveau 1 ou plus, vous récupérez des points de vie temporaires égaux au double du niveau du sort (ou du niveau du cantrip x votre niveau de magicien/2).$q$, null, null::jsonb),
      (60, 6, $q$Serviteurs morts-vivants$q$, $q$Quand vous lancez un sort qui crée des morts-vivants sous votre contrôle, ils gagnent des points de vie et des dégâts supplémentaires liés à votre niveau de magicien.$q$, null, null::jsonb),
      (60, 10, $q$Insensibilité à la non-vie$q$, $q$Votre maximum de points de vie augmente d'un montant égal à votre niveau de magicien, et vous gagnez la résistance aux dégâts nécrotiques.$q$, null, null::jsonb),
      (60, 14, $q$Contrôle des morts-vivants$q$, $q$Par une action, vous pouvez tenter de prendre le contrôle d'un mort-vivant à 18 m (JdS de Sagesse pour lui) pour un nombre d'heures égal à votre niveau de magicien.$q$, null, null::jsonb),
      (61, 2, $q$Transmutateur érudit$q$, $q$L'or et le temps nécessaires pour copier un sort de transmutation dans votre grimoire sont réduits de moitié.$q$, null, null::jsonb),
      (61, 2, $q$Alchimie mineure$q$, $q$Par 10 minutes de travail, vous transformez temporairement un matériau (bois, pierre, fer, cuivre, argent) en un autre pendant 1 heure.$q$, null, null::jsonb),
      (61, 6, $q$Pierre du transmutateur$q$, $q$Vous créez une pierre du transmutateur qui donne à son porteur, au choix, la vision dans le noir, une vitesse accrue, une compétence supplémentaire, ou la résistance à un type de dégâts.$q$, null, null::jsonb),
      (61, 10, $q$Métamorphe$q$, $q$Vous pouvez utiliser une action pour vous transformer magiquement, changeant votre apparence physique sans altérer vos capacités.$q$, null, '{"amount": 1, "rest_type": "repos_court"}'::jsonb),
      (61, 14, $q$Maître transmutateur$q$, $q$Vous pouvez utiliser votre Pierre du transmutateur pour lancer le sort transformation en pierre sans dépenser d'emplacement de sort, une fois entre deux repos longs.$q$, null, null::jsonb),
      (65, 3, $q$Arts des ombres$q$, $q$Vous pouvez dépenser 2 points de ki pour lancer, sans composante, l'un des sorts obscurité, silence, passe-partout ou détection de la magie.$q$, null, null::jsonb),
      (65, 6, $q$Foulée d'ombre$q$, $q$Vous pouvez vous téléporter jusqu'à 18 m d'une zone d'ombre à une autre en action bonus, à condition que les deux zones soient faiblement ou pas du tout éclairées.$q$, null, null::jsonb),
      (65, 11, $q$Linceul d'ombre$q$, $q$Dans une zone de faible luminosité ou d'obscurité, vous pouvez dépenser 3 points de ki pour devenir invisible tant que vous restez dans cette zone.$q$, null, null::jsonb),
      (65, 17, $q$Opportuniste$q$, $q$Quand une créature à 1,50 m de vous subit des dégâts d'une autre source que vous, vous pouvez utiliser votre réaction pour l'attaquer au corps à corps.$q$, null, null::jsonb),
      (66, 3, $q$Disciple des éléments$q$, $q$Vous apprenez des disciplines élémentaires (sorts-like alimentés par des points de ki) que vous pouvez lancer au lieu de sorts classiques, en utilisant la Sagesse comme caractéristique d'incantation.$q$, $q$discipline_elementaire$q$, null::jsonb),
      (66, 17, $q$Disciplines élémentaires$q$, $q$Vous apprenez de nouvelles disciplines élémentaires en montant de niveau, débloquant des effets tels que souffle de dragon, vague déferlante ou tempête de feu, chacune coûtant des points de ki.$q$, null, null::jsonb),
      (73, 1, $q$Liste de sorts étendue (Niveau de sort 1)$q$, $q$Liste de sorts étendue disponible au choix pour votre Magie de pacte, sorts de niveau 1 : Charme-personne, Sommeil.$q$, $q$sort_domaine$q$, null::jsonb),
      (73, 3, $q$Liste de sorts étendue (Niveau de sort 2)$q$, $q$Liste de sorts étendue, sorts de niveau 2 : Calme des émotions, Toile d'araignée.$q$, $q$sort_domaine$q$, null::jsonb),
      (73, 5, $q$Liste de sorts étendue (Niveau de sort 3)$q$, $q$Liste de sorts étendue, sorts de niveau 3 : Dissipation de la magie, Croissance végétale.$q$, $q$sort_domaine$q$, null::jsonb),
      (73, 7, $q$Liste de sorts étendue (Niveau de sort 4)$q$, $q$Liste de sorts étendue, sorts de niveau 4 : Domination de bête, Œil arcanique.$q$, $q$sort_domaine$q$, null::jsonb),
      (73, 9, $q$Liste de sorts étendue (Niveau de sort 5)$q$, $q$Liste de sorts étendue, sorts de niveau 5 : Domination de personne, Songe.$q$, $q$sort_domaine$q$, null::jsonb),
      (73, 1, $q$Présence féerique$q$, $q$Par une action, vous entourez d'une aura féerique une créature à 3 m que vous voyez (JdS de Sagesse), lui infligeant charme ou peur jusqu'à la fin de votre prochain tour.$q$, null, '{"amount": 1, "rest_type": "repos_court"}'::jsonb),
      (73, 6, $q$Échappatoire brumeuse$q$, $q$Quand vous subissez des dégâts, vous pouvez utiliser votre réaction pour devenir invisible et vous téléporter jusqu'à 18 m vers un espace inoccupé visible.$q$, null, '{"amount": 1, "rest_type": "repos_court"}'::jsonb),
      (73, 10, $q$Défenses captivantes$q$, $q$Quand une créature vous touche par une attaque de mêlée, vous pouvez utiliser votre réaction pour la forcer à effectuer un jet de sauvegarde de Sagesse ou devenir charmée par vous pendant 1 minute.$q$, null, null::jsonb),
      (73, 14, $q$Sombre délire$q$, $q$Vous pouvez plonger une créature charmée ou effrayée par vous dans un délire hypnotique, l'incapacitant tant qu'elle reste à 18 m de vous.$q$, null, '{"amount": 1, "rest_type": "repos_court"}'::jsonb),
