      (74, 1, $q$Esprit éveillé$q$, $q$Vous gagnez la télépathie avec toute créature que vous voyez à 9 m, sans qu'un langage commun soit nécessaire.$q$, null, null::jsonb),
      (74, 6, $q$Protection entropique$q$, $q$Quand une créature vous attaque, vous pouvez utiliser votre réaction pour lui imposer un désavantage à son jet, gagnant vous-même l'avantage à votre prochain jet de sauvegarde.$q$, null, '{"amount": 1, "rest_type": "repos_court"}'::jsonb),
      (74, 10, $q$Bouclier mental$q$, $q$Vous êtes en permanence protégé contre la détection des pensées, et quand vous subissez des dégâts psychiques, vous pouvez utiliser votre réaction pour les réduire de moitié.$q$, null, null::jsonb),
