      (7, 3, $q$Préceptes des anciens$q$, $q$Vous vous engagez à préserver la lumière, la beauté, l'amour et la vie face aux forces qui répandraient les ténèbres et le désespoir.$q$, null, null::jsonb),
      (7, 3, $q$Sorts de serment (Niveau de paladin 3)$q$, $q$Sorts de serment toujours préparés : Amitié avec les animaux, Ensorcellement.$q$, $q$sort_domaine$q$, null::jsonb),
      (7, 5, $q$Sorts de serment (Niveau de paladin 5)$q$, $q$Sorts de serment toujours préparés : Croissance végétale, Lueur d'espoir.$q$, $q$sort_domaine$q$, null::jsonb),
      (7, 9, $q$Sorts de serment (Niveau de paladin 9)$q$, $q$Sorts de serment toujours préparés : Dissipation de la magie, Reflets troublants.$q$, $q$sort_domaine$q$, null::jsonb),
      (7, 13, $q$Sorts de serment (Niveau de paladin 13)$q$, $q$Sorts de serment toujours préparés : Domination de bête, Liberté de mouvement.$q$, $q$sort_domaine$q$, null::jsonb),
      (7, 17, $q$Sorts de serment (Niveau de paladin 17)$q$, $q$Sorts de serment toujours préparés : Communion avec la nature, Mur de vent.$q$, $q$sort_domaine$q$, null::jsonb),
      (7, 3, $q$Conduit divin$q$, $q$Vous gagnez deux options de Conduit divin propres à ce serment : Éclat de la nature (une créature à 9 m subit un désavantage à son prochain jet de sauvegarde) et Rempart de la nature (vous devenez difficile à toucher et gagnez la résistance aux dégâts).$q$, null, null::jsonb),
      (7, 7, $q$Aura de garde$q$, $q$Vous et vos alliés à 3 m (9 m au niveau 18) êtes résistants aux dégâts infligés par les sorts.$q$, null, null::jsonb),
      (7, 15, $q$Sentinelle immortelle$q$, $q$Quand vous tombez à 0 point de vie sans être tué net, vous pouvez choisir de revenir à la place avec la moitié de vos points de vie maximum, une fois par repos long.$q$, null, '{"amount": 1, "rest_type": "repos_long"}'::jsonb),
      (7, 20, $q$Champion antique$q$, $q$Vous appelez la nature à votre aide : vos armes infligent des dégâts supplémentaires et vous gagnez une vitesse de vol temporaire pendant 1 minute, une fois par repos long.$q$, null, '{"amount": 1, "rest_type": "repos_long"}'::jsonb),
      (84, 3, $q$Préceptes de vengeance$q$, $q$Vous vous engagez à traquer et punir sans relâche ceux qui commettent de grands maux, quel qu'en soit le prix personnel.$q$, null, null::jsonb),
      (84, 3, $q$Sorts de serment (Niveau de paladin 3)$q$, $q$Sorts de serment toujours préparés : Marque du chasseur, Punition sanglante.$q$, $q$sort_domaine$q$, null::jsonb),
      (84, 5, $q$Sorts de serment (Niveau de paladin 5)$q$, $q$Sorts de serment toujours préparés : Immobilisation de personne, Repli sinistre.$q$, $q$sort_domaine$q$, null::jsonb),
      (84, 9, $q$Sorts de serment (Niveau de paladin 9)$q$, $q$Sorts de serment toujours préparés : Anti-détection, Repérage.$q$, $q$sort_domaine$q$, null::jsonb),
      (84, 13, $q$Sorts de serment (Niveau de paladin 13)$q$, $q$Sorts de serment toujours préparés : Bannissement, Œil arcanique.$q$, $q$sort_domaine$q$, null::jsonb),
      (84, 17, $q$Sorts de serment (Niveau de paladin 17)$q$, $q$Sorts de serment toujours préparés : Domination de personne, Scrutation.$q$, $q$sort_domaine$q$, null::jsonb),
      (84, 3, $q$Conduit divin$q$, $q$Vous gagnez deux options de Conduit divin propres à ce serment : Menace abjuratoire (une créature à 9 m a un désavantage à ses attaques contre des cibles autres que vous) et Vœu d'inimitié (avantage à vos jets d'attaque contre une créature choisie pendant 1 minute).$q$, null, null::jsonb),
      (84, 7, $q$Vengeur implacable$q$, $q$Quand une créature que vous avez touchée à votre dernier tour se déplace sans votre permission, vous pouvez utiliser votre réaction pour vous déplacer avec elle jusqu'à sa vitesse, sans provoquer d'attaque d'opportunité.$q$, null, null::jsonb),
      (84, 15, $q$Âme vengeresse$q$, $q$Votre vitesse augmente de 3 m tant que vous n'êtes pas incapable d'agir, et les créatures que vous prenez en chasse ne peuvent pas bénéficier de la Discrétion contre vous.$q$, null, null::jsonb),
      (84, 20, $q$Ange de la vengeance$q$, $q$Par une action, vous vous transformez, faisant pousser des ailes spectrales vous octroyant une vitesse de vol de 18 m et imposant la peur à vos ennemis à 9 m (JdS de Sagesse), une fois par repos long.$q$, null, '{"amount": 1, "rest_type": "repos_long"}'::jsonb),
      (89, 3, $q$Compagnon du rôdeur$q$, $q$Vous gagnez un compagnon animal (bête de FP 1/4 maximum) qui combat à vos côtés et agit à votre initiative.$q$, null, null::jsonb),
      (89, 7, $q$Entraînement exceptionnel$q$, $q$Votre compagnon animal peut, sans utiliser votre action, se déplacer et effectuer une action (Attaquer, Aider, Esquiver, Se cacher) de son propre chef.$q$, null, null::jsonb),
      (89, 11, $q$Fureur bestiale$q$, $q$Vous pouvez ordonner à votre compagnon d'attaquer deux fois lorsque vous utilisez votre action pour l'ordre Attaquer.$q$, null, null::jsonb),
      (89, 15, $q$Partage des sorts$q$, $q$Quand vous lancez un sort sur vous-même, vous pouvez aussi affecter votre compagnon animal s'il est à 9 m ou moins.$q$, null, null::jsonb),
      (91, 3, $q$Don draconique$q$, $q$Vous gagnez un don lié aux dragons (par exemple Interprète draconique ou Résilience draconique) qui renforce votre lien avec votre futur compagnon drake.$q$, null, null::jsonb),
      (91, 3, $q$Compagnon drake$q$, $q$Un œuf de dragon magique éclot à votre contact, vous liant à un drake compagnon qui grandit et combat à vos côtés, agissant à votre initiative.$q$, null, '{"amount": 1, "rest_type": "repos_long"}'::jsonb),
      (91, 7, $q$Lien du croc et d'écailles$q$, $q$Vous et votre drake bénéficiez d'un bonus mutuel aux jets d'attaque ou de dégâts lorsque vous combattez à proximité l'un de l'autre.$q$, null, null::jsonb),
      (91, 11, $q$Souffle de drake$q$, $q$Votre drake peut utiliser une action pour exhaler un souffle d'énergie élémentaire (type déterminé par son ascendance), infligeant des dégâts dans une zone avec jet de sauvegarde.$q$, null, '{"amount": 1, "rest_type": "repos_long"}'::jsonb),
      (91, 15, $q$Lien parfait$q$, $q$Votre drake atteint sa taille adulte, gagnant des points de vie, une attaque et un souffle plus puissants, ainsi qu'une plus grande autonomie au combat.$q$, null, null::jsonb),
      (96, 3, $q$Maîtrises supplémentaires$q$, $q$Vous gagnez la maîtrise des outils de déguisement et des outils d'empoisonneur.$q$, null, null::jsonb),
      (96, 3, $q$Assassinat$q$, $q$Vous avez l'avantage aux jets d'attaque contre toute créature qui n'a pas encore agi lors du combat, et toute attaque réussie contre une créature surprise est un coup critique.$q$, null, null::jsonb),
      (96, 9, $q$Expert en infiltration$q$, $q$Vous pouvez passer 1 heure à adopter une nouvelle identité (apparence, voix, manières) crédible sans magie.$q$, null, null::jsonb),
      (96, 13, $q$Imposteur$q$, $q$Vous pouvez imiter parfaitement l'écriture, la voix et le comportement d'une autre personne après une observation suffisante.$q$, null, null::jsonb),
      (96, 17, $q$Frappe meurtrière$q$, $q$Quand vous touchez une créature surprise, elle doit réussir un jet de sauvegarde de Constitution (DD égal à votre attaque sournoise + votre modificateur de Dextérité) ou subir le double des dégâts de l'attaque.$q$, null, null::jsonb),
      (97, 3, $q$Incantation$q$, $q$Vous apprenez à lancer des sorts de magicien (surtout école d'illusion et d'enchantement), en utilisant l'Intelligence comme caractéristique d'incantation, avec une progression lente (un tiers de votre niveau de roublard).$q$, null, null::jsonb),
      (97, 3, $q$Escamotage et main de mage$q$, $q$Vous apprenez le cantrip main de mage, et pouvez le rendre invisible et l'utiliser pour voler ou manipuler des objets à distance en action bonus, en lien avec votre Ruse.$q$, null, null::jsonb),
      (97, 9, $q$Embuscade magique$q$, $q$Quand vous êtes invisible au moment de lancer un sort sur une créature, celle-ci a un désavantage à son jet de sauvegarde contre ce sort.$q$, null, null::jsonb),
      (97, 13, $q$Escroc polyvalent$q$, $q$Vous pouvez remplacer l'effet de votre main de mage invisible par un tour de passe-passe de votre choix, comme distraire une créature à distance.$q$, null, null::jsonb),
      (97, 17, $q$Voleur de sort$q$, $q$Après avoir mis hors de combat une créature capable de lancer des sorts, vous pouvez lui dérober un sort qu'elle avait préparé et le lancer vous-même une fois avant la fin de votre prochain repos long.$q$, null, '{"amount": 1, "rest_type": "repos_long"}'::jsonb),
      (100, 3, $q$Maître des intrigues$q$, $q$Vous pouvez imiter l'accent et le dialecte d'une autre personne après l'avoir écoutée pendant 1 minute, et vous gagnez deux outils de jeu ou langues supplémentaires.$q$, null, null::jsonb),
      (100, 3, $q$Maître des tactiques$q$, $q$Par une action bonus, vous aidez à distance : une créature alliée qui peut vous entendre gagne l'avantage à son prochain jet d'attaque ou de compétence avant la fin de votre prochain tour.$q$, null, null::jsonb),
      (100, 9, $q$Manipulateur perspicace$q$, $q$Après avoir parlé avec une créature pendant au moins 1 minute, vous pouvez apprendre si elle a l'intention de mentir, ses attitudes et centres d'intérêt émotionnels.$q$, null, null::jsonb),
      (100, 13, $q$Redirection$q$, $q$Quand une créature vous touche par une attaque de mêlée, vous pouvez utiliser votre réaction pour désigner une autre créature à 1,50 m qui devient la cible de l'attaque à votre place.$q$, null, null::jsonb),
      (100, 17, $q$Âme de trompeur$q$, $q$Vous pouvez utiliser votre action bonus d'Aide à distance sur deux créatures alliées à la fois, et Manipulateur perspicace vous permet aussi d'implanter une fausse impression durable.$q$, null, null::jsonb)
    ) as t(subclass_id, level, name, description, choice_type, uses_per_rest)
  loop
    if not exists (
      select 1 from public.class_features cf
      join public.translations n on n.entity_type = 'class_feature' and n.entity_id = cf.id::text and n.field_name = 'name' and n.locale = 'fr'
      where cf.subclass_id = rec.subclass_id and cf.level = rec.level and n.value = rec.name
    ) then
      insert into public.class_features (class_id, subclass_id, level, choice_type, uses_per_rest)
        values (null, rec.subclass_id, rec.level, rec.choice_type, rec.uses_per_rest)
        returning id into v_id;
      insert into public.translations (entity_type, entity_id, field_name, locale, value) values
        ('class_feature', v_id::text, 'name', 'fr', rec.name),
        ('class_feature', v_id::text, 'description', 'fr', rec.description);
    end if;
  end loop;
end $$;
